package com.arjunren.hospital.controller;
import com.arjunren.hospital.dto.Dtos.LoginRequest;import com.arjunren.hospital.entity.AppUser;import com.arjunren.hospital.exception.DomainException;import com.arjunren.hospital.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/auth")public class AuthController{private final AuthService auth;private final LoginRateLimiter limiter;public AuthController(AuthService a,LoginRateLimiter l){auth=a;limiter=l;}@PostMapping("/login")Map<String,Object>login(@Valid@RequestBody LoginRequest r,HttpServletRequest req){limiter.check(req.getRemoteAddr());return Map.of("data",auth.login(r));}@PostMapping("/logout")@ResponseStatus(HttpStatus.NO_CONTENT)void logout(@AuthenticationPrincipal AppUser u,HttpServletRequest req){String h=req.getHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new DomainException(HttpStatus.UNAUTHORIZED,"Bearer token required");auth.logout(h.substring(7));}}
